let section=new URLSearchParams(location.search).get('section')||'home';if(!sections[section])section='home';
let state=emptyState(),active=false,busy=false,month=monthNow(),search='',filter='all',syncTime=null,syncError='',poll=null,requestSeq=0,installPrompt=null,receiptUrl=null,pendingPayload=null,editedId=null,googleInitialized=false,loginNonce='',pushStatus='unknown',settlePreset=null;
