function nowTime(){return new Intl.DateTimeFormat('es-ES',{timeZone:'Europe/Madrid',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());}
function rows(table){return state[table].filter(r=>!r.deleted);}
function loginScreen(message=''){
 active=false;clearInterval(poll);requestSeq++;api.logout();state=emptyState();pendingPayload=null;operationRetries.clear();
 $('#app').innerHTML=`<div class="login-wrap"><div class="login-brand"><a class="brand" href="./"><span class="brand-symbol">m<span>y</span>c<small>♡</small></span><span>NUESTRO HOGAR</span></a><span class="private-label">${icon('heart')} Solo tú y yo</span></div><main id="main" class="login-main"><div class="login-copy"><span class="eyebrow">MARÍA + CARLOS</span><h1>La vida juntos,<br>un poquito <br><em>más fácil.</em></h1><p>Las cuentas claras, la compra a mano y más tiempo para nosotros. Bienvenidos a nuestro hogar.</p><div class="login-actions"><div id="google-button"></div>${!CONFIG.apiUrl?'<p class="setup-note">La conexión privada con Google está pendiente de configurar. Puedes explorar la aplicación con datos de ejemplo.</p>':''}<button class="btn ${CONFIG.apiUrl?'secondary':''}" data-action="demo">${icon('home')} Probar con datos de ejemplo ${icon('arrow')}</button>${message?`<p role="alert" class="error-text">${esc(message)}</p>`:''}<small>Solo las dos cuentas autorizadas podrán acceder a los datos reales.</small></div></div><div class="login-art"><div class="art-circle"></div><img class="couple-art" src="./assets/icon-512.png" alt="Caricaturas de Carlos y María en nuestra casa"><span class="art-note note-one">Un equipo para todo ${icon('heart')}</span><span class="art-note note-two">Nuestra casa. Nuestras cosas.</span></div></main><div class="login-features">${[['gastos','Gastos sin líos'],['tareas','Cada cosa a su tiempo'],['compra','Que no falte nada'],['mensajes','Un mensaje para ti']].map(([img,title])=>`<div><img src="./assets/${img}.png" alt=""><span>${title}</span></div>`).join('')}</div><footer class="login-footer">Hecho para nosotros <span>MYC · María y Carlos</span></footer></div>`;
 if(CONFIG.apiUrl&&CONFIG.googleClientId)loadGoogle();
}
async function loadGoogle(){
 if(!window.google){let script=document.querySelector('#gis');if(!script){script=document.createElement('script');script.id='gis';script.src='https://accounts.google.com/gsi/client';script.async=true;document.head.append(script);}script.onload=initializeGoogle;script.onerror=()=>toast('No se pudo cargar el acceso con Google. Comprueba la conexión.');}
 else initializeGoogle();
}
function initializeGoogle(){
 if(!$('#google-button'))return;
 if(!googleInitialized){loginNonce=crypto.randomUUID();window.google.accounts.id.initialize({client_id:CONFIG.googleClientId,nonce:loginNonce,auto_select:true,use_fedcm_for_prompt:true,cancel_on_tap_outside:false,callback:async credential=>{const wasActive=active;try{const payload=JSON.parse(atob(credential.credential.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.nonce!==loginNonce)throw new Error('Respuesta de acceso no válida.');const data=await api.authenticate(credential.credential);if(wasActive&&active){$('#reauth')?.remove();toast('Sesión renovada. Puedes seguir donde lo dejaste ♡');sync(true,true);}else{state=data;startApp();}}catch(e){if(wasActive&&active)reauth(e.message);else loginScreen(e.message);}}});googleInitialized=true;}
 window.google.accounts.id.renderButton($('#google-button'),{theme:'outline',size:'large',text:'signin_with',shape:'pill',width:280,locale:'es'});if(!active)window.google.accounts.id.prompt();
}
// Si la sesión caduca, no se cierra nada: se pide entrar de nuevo encima de lo que estabas haciendo.
function reauth(message){
 api.logout();clearInterval(poll);
 let box=$('#reauth');if(!box){box=document.createElement('div');box.id='reauth';box.setAttribute('role','alertdialog');box.setAttribute('aria-labelledby','reauth-title');}
 box.innerHTML=`<div class="reauth-card"><span class="eyebrow">SESIÓN</span><h2 id="reauth-title">Vuelve a entrar para guardar</h2><p>${esc(message||'Tu sesión ha caducado.')} No se ha perdido nada de lo que estabas haciendo.</p><div id="google-button"></div></div>`;
 (modal.open?modal:document.body).append(box);
 if(CONFIG.apiUrl&&CONFIG.googleClientId)loadGoogle();
}
async function boot(){
 if(!api.hasSession()){loginScreen();return;}
 try{state=await api.snapshot();startApp();}
 catch(e){
  if(e.code==='UNAUTHORIZED'||e.code==='FORBIDDEN'){loginScreen(e.message);return;}
  $('#app').innerHTML=`<main class="boot"><img src="./assets/icon-192.png" alt="" width="96" height="96"><h1>MYC</h1><p>${esc(e.message)}</p><button class="btn" data-action="retry-boot">${icon('refresh')} Reintentar</button></main>`;
 }
}
function startApp(){active=true;$('#reauth')?.remove();syncTime=new Date();syncError='';render();clearInterval(poll);poll=setInterval(()=>sync(true),30000);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.waiting)toast('Hay una nueva versión. Cierra y vuelve a abrir MYC para actualizar.');reg.addEventListener('updatefound',()=>{const sw=reg.installing;sw?.addEventListener('statechange',()=>{if(sw.state==='installed'&&navigator.serviceWorker.controller)toast('Nueva versión disponible. Cierra y vuelve a abrir MYC.');});});}).catch(()=>{});}
function render(){
 if(!active)return;
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#home" data-nav="home"><span class="brand-symbol">m<span>y</span>c<small>♡</small></span><span>NUESTRO HOGAR</span></a><p class="sidebar-caption">TODO LO NUESTRO</p><nav aria-label="Navegación principal">${Object.entries(sections).map(([k,[,title]])=>`<button data-nav="${k}" class="nav-item ${section===k?'selected':''}" ${section===k?'aria-current="page"':''}>${icon(k)}<span>${title}</span>${k==='messages'&&rows('messages').filter(m=>!m.resolved&&(m.to===api.user||m.to==='Ambos')).length?`<b>${rows('messages').filter(m=>!m.resolved&&(m.to===api.user||m.to==='Ambos')).length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="little-home">${icon('heart')} <span>Mejor, juntos.<small>Un hogar, un equipo.</small></span></div><div class="signed-user">${avatar(api.user)}<span>${esc(api.user)}<small>En nuestra casa</small></span><button class="icon-btn" data-action="logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></div></aside><div class="workspace">${api.demo?'<div class="demo-banner"><span>Modo de prueba · Datos de ejemplo guardados solo en este navegador</span><button data-action="logout">Salir de la prueba</button></div>':''}<header class="topbar"><div class="breadcrumbs">Nuestro hogar <span>/</span> <strong>${sections[section][1]}</strong></div><div class="topbar-right"><button class="sync-indicator ${syncError?'sync-failed':''}" data-action="sync" aria-label="Actualizar datos">${icon('refresh')} <span>${!navigator.onLine?'Sin conexión':syncError?'Reintentar sincronización':busy?'Guardando…':syncTime?'Actualizado '+syncTime.toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}):'Sincronizando…'}</span></button><div class="avatar-duo">${avatar('Carlos')}${avatar('María')}</div></div></header><main id="main" tabindex="-1">${syncError?`<div class="inline-alert" role="alert">${esc(syncError)}</div>`:''}${page()}</main><footer class="app-footer">Un poquito de orden. Mucho de nosotros. ${icon('heart')}<span>MYC · María y Carlos</span></footer></div><nav class="mobile-nav" aria-label="Navegación móvil">${['home','expenses','tasks','shopping','messages'].map(k=>`<button data-nav="${k}" aria-label="${sections[k][1]}" ${section===k?'aria-current="page"':''} class="${section===k?'selected':''}">${icon(k)}<span>${k==='tasks'?'Recorda<wbr>torios':sections[k][1]}</span></button>`).join('')}<button data-nav="settings" class="${section==='settings'?'selected':''}" aria-label="Ajustes">${icon('settings')}<span>Ajustes</span></button></nav></div>`;
}
function page(){return ({home:homePage,expenses:expensePage,tasks:taskPage,shopping:shoppingPage,messages:messagePage,settings:settingsPage}[section])();}
function heading(title,subtitle,action,button,art){return `<div class="page-heading"><div><span class="eyebrow">${section==='home'?'NUESTRO RINCÓN':'TODO LO NUESTRO'}</span><h1>${title}</h1><p>${subtitle}</p></div>${art?`<img class="heading-art" src="./assets/${art}.png" alt="">`:''}${action?`<button class="btn" data-action="${action}">${icon('plus')}${button}</button>`:''}</div>`;}
function empty(title,description,art='tareas'){return `<div class="empty-state"><img src="./assets/${art}.png" alt=""><h3>${title}</h3><p>${description}</p></div>`;}
function homePage(){
 const expenses=rows('expenses'),current=expenses.filter(e=>e.date.startsWith(monthNow())),house=current.filter(e=>e.purpose==='household'),total=house.reduce((a,e)=>a+e.amount,0),budget=rows('budgets').find(b=>b.month===monthNow())?.amount||0,pending=rows('tasks').filter(t=>!t.done),groceries=rows('shopping').filter(t=>!t.checked),b=balance(expenses,rows('settlements'));
 const greeting=new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'});
 return `<section class="welcome"><div><span class="eyebrow">${esc(greeting)}</span><h1>Hola, ${esc(api.user)} <span class="wave">☀️</span></h1><p>Qué bien tenerte en casa.</p><div class="welcome-note">${icon('heart')} Las pequeñas cosas también se cuidan.</div></div><img src="./assets/icon-512.png" alt="Carlos y María, juntos en casa"></section><div class="section-title"><h2>¿Qué organizamos hoy?</h2><span>Un espacio para los dos</span></div><div class="shortcut-grid">${[['expenses','gastos','Gastos y tickets','Cada cuenta, en su sitio.'],['tasks','tareas','Recordatorios','Que nada se nos pase.'],['shopping','compra','La compra','Que no se nos olvide nada.'],['messages','mensajes','Para ti','Lo que quería contarte.']].map(([nav,img,title,description])=>`<button class="shortcut ${nav}" data-nav="${nav}"><div><h3>${title}</h3><p>${description}</p><span class="round-arrow">${icon('arrow')}</span></div><img src="./assets/${img}.png" alt=""></button>`).join('')}</div><div class="dashboard-grid"><section class="panel expense-summary"><div class="panel-head"><h2>Así va nuestro mes</h2><span class="pill">${esc(new Intl.DateTimeFormat('es-ES',{month:'long'}).format(new Date()))}</span></div><div class="big-number">${money(total)} <small>en gastos de casa</small></div>${budget?`<div class="budget-progress"><div><span>${money(Math.max(0,budget-total))} ${total>budget?'· presupuesto superado':'disponibles'}</span><strong>${Math.round(total/budget*100)} %</strong></div><progress max="${budget}" value="${Math.min(total,budget)}" aria-label="Presupuesto mensual"></progress><small>Presupuesto: ${money(budget)}</small></div>`:'<p class="muted">Podéis fijar vuestro presupuesto en Ajustes.</p>'}<div class="balance-box"><span>${icon('expenses')} <strong>Entre nosotros</strong><small>Saldo acumulado · casa y compras personales</small></span><b>${Math.abs(b)<1?'Todo al día ♡':`${b>0?'María debe a Carlos':'Carlos debe a María'}<strong>${money(Math.abs(b))}</strong>`}</b></div><button class="text-btn" data-nav="expenses">Ver todas las cuentas ${icon('arrow')}</button></section><section class="panel"><div class="panel-head"><h2>Próximos recordatorios</h2><button class="text-btn" data-nav="tasks">Ver todo ${icon('arrow')}</button></div>${pending.length?`<div class="compact-list">${pending.sort((a,b)=>((a.due||'9999')+(a.time||'99')).localeCompare((b.due||'9999')+(b.time||'99'))).slice(0,3).map(t=>taskRow(t,true)).join('')}</div>`:'<p class="nice-empty">Nada pendiente. ¿Un ratito para nosotros? ☕</p>'}<button class="shopping-reminder" data-nav="shopping"><span class="shopping-bag">🛍️</span><span><strong>${groceries.length?`${groceries.length} cosas en la lista`:'La lista está al día'}</strong><small>La próxima compra empieza aquí</small></span>${icon('arrow')}</button></section></div><section class="panel recent-panel"><div class="panel-head"><h2>Los últimos gastos</h2><button class="text-btn" data-action="new-expenses">Añadir gasto ${icon('plus')}</button></div>${expenses.length?expenses.sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,4).map(expenseRow).join(''):empty('Las cuentas empiezan aquí','Añadid vuestro primer gasto de casa.','gastos')}</section>`;
}
function monthControl(){return `<div class="month-picker"><button class="icon-btn" data-action="prev-month" aria-label="Mes anterior">‹</button><label><span class="sr-only">Mes de los gastos</span><input aria-label="Mes de los gastos" type="month" id="month" value="${month}" min="2000-01" max="2100-12"></label><button class="icon-btn" data-action="next-month" aria-label="Mes siguiente">›</button></div>`;}
function expensePage(){
 const all=rows('expenses'),inMonth=all.filter(e=>e.date.startsWith(month)),list=inMonth.filter(e=>(filter==='all'||e.purpose===filter)&&`${e.title} ${e.store} ${e.category} ${e.paidBy}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)),house=inMonth.filter(e=>e.purpose==='household').reduce((a,e)=>a+e.amount,0),personal=inMonth.filter(e=>e.purpose!=='household').reduce((a,e)=>a+e.amount,0),b=balance(all,rows('settlements'));
 return heading('Las cuentas, claras.','Lo de casa y lo de cada uno. Sin echar cuentas dos veces.','new-expenses','Añadir gasto','gastos')+`<div class="stat-grid"><div class="stat-card"><span>Gastos de casa · mes</span><strong>${money(house)}</strong><small>${inMonth.filter(e=>e.purpose==='household').length} tickets compartidos</small></div><div class="stat-card"><span>Compras personales · mes</span><strong>${money(personal)}</strong><small>Reembolso al 100 % al que pagó</small></div><div class="stat-card balance-stat"><span>Saldo pendiente · todos los meses</span><strong>${money(Math.abs(b))}</strong><small>${b===0?'Estáis al día':b>0?'María debe a Carlos':'Carlos debe a María'}</small><button class="text-btn" data-action="settle">Registrar un pago ${icon('arrow')}</button></div></div>${monthAccounts(inMonth)}${thermometers(inMonth)}<section class="panel"><div class="list-toolbar">${monthControl()}<label class="search-field"><span class="sr-only">Buscar gastos</span><input id="search" type="search" placeholder="Buscar gasto, tienda…" value="${esc(search)}"></label><button class="icon-btn" data-action="export-csv" aria-label="Exportar gastos de este mes en CSV">${icon('download')}</button></div><div class="tabs" aria-label="Tipo de gasto">${[['all','Todos'],['household','De casa'],['Carlos','Para Carlos'],['María','Para María']].map(([id,title])=>`<button class="${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${title}</button>`).join('')}</div><div id="expense-results">${list.length?list.map(expenseRow).join(''):empty('Aquí todavía no hay gastos','Añade uno o cambia el mes y los filtros.','gastos')}</div><div class="list-total"><span>${list.length} gastos en esta vista</span><strong>${money(list.reduce((a,e)=>a+e.amount,0))}</strong></div></section><div class="two-columns"><section class="panel"><div class="panel-head"><h2>Casa, por categorías</h2></div>${categoryChart(inMonth.filter(e=>e.purpose==='household'))}</section><section class="panel"><div class="panel-head"><h2>Pagos entre nosotros</h2><button class="text-btn" data-action="settle">Registrar ${icon('plus')}</button></div><p class="muted small">Estos pagos reducen la deuda. No cuentan como gasto de casa.</p>${rows('settlements').length?rows('settlements').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10).map(s=>`<div class="list-row"><span class="store-icon green">↔</span><div class="row-main"><strong>${esc(s.from)} → ${s.from==='Carlos'?'María':'Carlos'}</strong><small>${dateLabel(s.date)} ${esc(s.notes)}</small></div><b>${money(s.amount)}</b><button class="icon-btn" data-edit="settlements" data-id="${s.id}" aria-label="Editar pago">${icon('edit')}</button></div>`).join(''):'<p class="nice-empty">Cuando os paguéis, apuntadlo aquí.</p>'}</section></div>`;
}
// Termómetros: lo que cada uno lleva pagado de su bolsillo en el mes (casa + compras para el otro o para sí).
let thermoSeen='';
function thermometers(inMonth){
 const paid=p=>inMonth.filter(e=>e.paidBy===p),sum=l=>l.reduce((a,e)=>a+e.amount,0);
 const data=PEOPLE.map(p=>{const l=paid(p);return {p,total:sum(l),house:sum(l.filter(e=>e.purpose==='household')),n:l.length};});
 const max=Math.max(...data.map(d=>d.total),1),all=data.reduce((a,d)=>a+d.total,0);
 const animate=thermoSeen!==month;thermoSeen=month;
 const tube=d=>{const pct=Math.round(d.total/max*100),share=all?Math.round(d.total/all*100):0;return `<div class="thermo ${d.p==='Carlos'?'carlos':'maria'}"><div class="thermo-amount"><strong>${money(d.total)}</strong><small>${share} % del mes</small></div><div class="thermo-body" role="img" aria-label="${esc(d.p)} ha pagado ${money(d.total)} este mes"><div class="thermo-tube"><div class="thermo-ticks"></div><div class="thermo-fill ${animate?'grow':''}" style="--h:${Math.max(pct,d.total?4:0)}%"></div></div><div class="thermo-bulb"></div></div><div class="thermo-who">${avatar(d.p)}<span>${esc(d.p)}<small>${d.n} ${d.n===1?'pago':'pagos'} · casa ${money(d.house)}</small></span></div></div>`;};
 const lead=data[0].total===data[1].total?'Vais igualados':`${data[0].total>data[1].total?'Carlos':'María'} lleva ${money(Math.abs(data[0].total-data[1].total))} más`;
 return `<section class="panel thermo-panel"><div class="panel-head"><h2>Lo que lleva pagado cada uno</h2><span class="thermo-lead">${all?lead:''}</span></div><p class="muted small">Todo lo que ha salido del bolsillo de cada uno este mes, de casa o personal.</p><div class="thermo-row">${data.map(tube).join('')}</div></section>`;
}
// Cuentas del mes: resumen muy claro de quién debe a quién (casa según el reparto; personales al 100 %).
function monthAccounts(inMonth){
 const mariaOwes=[],carlosOwes=[];
 for(const e of inMonth){const carlosPart=Math.round(e.amount*e.carlosPercent/100),mariaPart=e.amount-carlosPart;if(e.paidBy==='Carlos'&&mariaPart>0)mariaOwes.push([e,mariaPart]);if(e.paidBy==='María'&&carlosPart>0)carlosOwes.push([e,carlosPart]);}
 const sum=l=>l.reduce((a,[,v])=>a+v,0),m=sum(mariaOwes),c=sum(carlosOwes);
 const paid=rows('settlements').filter(s=>s.date.startsWith(month)),paidM=paid.filter(s=>s.from==='María').reduce((a,s)=>a+s.amount,0),paidC=paid.filter(s=>s.from==='Carlos').reduce((a,s)=>a+s.amount,0);
 const net=m-c-paidM+paidC,payer=net>0?'María':'Carlos',receiver=net>0?'Carlos':'María';
 const monthName=new Intl.DateTimeFormat('es-ES',{month:'long'}).format(new Date(month+'-15T12:00:00Z'));
 const why=e=>e.purpose==='household'?`de casa · le toca el ${e.paidBy==='Carlos'?100-e.carlosPercent:e.carlosPercent} % de ${money(e.amount)}`:`es solo para ${e.purpose} · 100 % de ${money(e.amount)}`;
 const detail=l=>l.length?`<details class="debt-why"><summary>¿De dónde sale?</summary>${l.sort((a,b)=>a[0].date.localeCompare(b[0].date)).map(([e,v])=>`<div class="debt-why-item"><span><strong>${esc(e.title)}</strong><small>${dateLabel(e.date)} · pagó ${esc(e.paidBy)} · ${why(e)}</small></span><b>${money(v)}</b></div>`).join('')}</details>`:'';
 const line=(sign,who,text,amount,l,cls='')=>`<div class="debt-line ${cls}"><span class="debt-sign">${sign}</span>${who?avatar(who):''}<div class="debt-text"><span>${text}</span></div><b>${money(amount)}</b>${l&&l.length?`<div class="debt-why-wrap">${detail(l)}</div>`:''}</div>`;
 const hero=net===0?`<div class="debt-hero even"><div class="debt-faces">${avatar('María','large')}<span class="debt-heart">♡</span>${avatar('Carlos','large')}</div><strong>Estáis en paz</strong><small>Nadie debe nada en ${esc(monthName)}.</small></div>`
  :`<div class="debt-hero"><div class="debt-faces">${avatar(payer,'large')}<span class="debt-arrow"><b>${money(Math.abs(net))}</b><svg viewBox="0 0 120 24" aria-hidden="true"><path d="M2 12h110m-12-9 12 9-12 9" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></span>${avatar(receiver,'large')}</div><strong>${payer} le da a ${receiver} ${money(Math.abs(net))}</strong><small>y quedáis en paz en ${esc(monthName)}.</small></div>`;
 const math=(m||c||paidM||paidC)?`<div class="debt-math"><h3>La cuenta, paso a paso</h3>${line('+','María','María le debe a Carlos',m,mariaOwes)}${line('−','Carlos','Carlos le debe a María',c,carlosOwes)}${paidM?line('−','María','María ya le ha pagado a Carlos',paidM,null,'paid'):''}${paidC?line('+','Carlos','Carlos ya le ha pagado a María',paidC,null,'paid'):''}<div class="debt-total"><span>=</span><div>${net===0?'Nadie debe nada':`${payer} paga a ${receiver}`}</div><b>${money(Math.abs(net))}</b></div></div>`:'<p class="nice-empty">Todavía no hay gastos este mes.</p>';
 return `<section class="panel debt-summary"><div class="panel-head"><h2>¿Quién debe a quién?</h2><span class="debt-month">${esc(monthName)}</span></div>${hero}${math}${net?`<button class="btn debt-pay" data-action="settle-month" data-from="${payer}" data-amount="${Math.abs(net)}">${icon('check')} Ya se lo ha pagado: apuntarlo</button>`:''}<p class="small muted debt-rule">Gastos de casa: cada uno su parte. Cosas de uno pagadas por el otro: se devuelven enteras.</p></section>`;
}
function categoryChart(list){const total=list.reduce((a,e)=>a+e.amount,0);return total?CATEGORIES.map(c=>{const sum=list.filter(e=>e.category===c).reduce((a,e)=>a+e.amount,0);return sum?`<div class="category-row"><span>${catIcon(c,'small')}${esc(c)}</span><b>${money(sum)}</b><progress max="${total}" value="${sum}" aria-label="${esc(c)}"></progress></div>`:'';}).join(''):'<p class="nice-empty">El reparto aparecerá con vuestro primer gasto de casa.</p>';}
function expenseRow(e){return `<div class="list-row expense-row">${catIcon(e.category,'row '+(e.purpose==='household'?'':'personal'))}<div class="row-main"><strong>${esc(e.title)}</strong><small>${storeEmoji(e.store)} ${esc(e.store)} · ${esc(e.category)} · ${dateLabel(e.date)} · Pagó ${esc(e.paidBy)}</small></div><span class="pill expense-purpose ${e.purpose!=='household'?'pink-pill':''}">${e.purpose==='household'?`Casa · ${e.carlosPercent}/${100-e.carlosPercent}`:`Para ${esc(e.purpose)} · 100 %`}</span><b class="row-amount">${money(e.amount)}</b>${e.receiptId||e.demoReceipt?`<button class="icon-btn" data-receipt="${e.id}" aria-label="Ver ticket de ${esc(e.title)}">${icon('receipt')}</button>`:''}<button class="icon-btn" data-edit="expenses" data-id="${e.id}" aria-label="Editar ${esc(e.title)}">${icon('edit')}</button></div>`;}
function taskRow(t,compact=false){return `<div class="list-row task-row ${t.done?'is-done':''}"><button class="check-btn ${t.done?'checked':''}" data-toggle="tasks" data-id="${t.id}" aria-label="${t.done?'Reabrir':'Completar'} ${esc(t.title)}">${t.done?icon('check'):''}</button><div class="row-main"><strong>${esc(t.title)}</strong><small class="${!t.done&&t.due&&(t.due<today()||(t.due===today()&&t.time&&t.time<nowTime()))?'overdue':''}">${t.due===today()?'Hoy':dateLabel(t.due)}${t.due&&t.time?' · '+t.time:''}${t.due&&!t.done&&remindList(t).length?' · 🔔 '+remindList(t).map(v=>REMIND_SHORT[v]).join(', '):''}${t.recurrence!=='none'?' · '+({daily:'Cada día',weekly:'Cada semana',monthly:'Cada mes'}[t.recurrence]):''}${t.lastCompletedAt?' · Repetida ✓':''}</small>${!compact&&t.notes?`<p>${esc(t.notes)}</p>`:''}</div><span class="assignee">${t.assignedTo==='Ambos'?'<span class="both-avatar">♡</span>':avatar(t.assignedTo)}<small>${esc(t.assignedTo)}</small></span>${!compact?`<button class="icon-btn" data-edit="tasks" data-id="${t.id}" aria-label="Editar ${esc(t.title)}">${icon('edit')}</button>`:''}</div>`;}
function taskPage(){const list=rows('tasks').filter(t=>filter==='all'?true:filter==='done'?t.done:filter==='pending'?!t.done:(t.assignedTo===api.user||t.assignedTo==='Ambos')&&!t.done).sort((a,b)=>Number(a.done)-Number(b.done)||((a.due||'9999')+(a.time||'99')).localeCompare((b.due||'9999')+(b.time||'99')));return heading('Que no se nos olvide.','Lo que tenemos pendiente, a su tiempo.','new-tasks','Añadir recordatorio','tareas')+`<div class="mini-stats"><span><b>${rows('tasks').filter(t=>!t.done).length}</b> pendientes</span><span><b>${rows('tasks').filter(t=>!t.done&&t.due===today()).length}</b> para hoy</span><span><b>${rows('tasks').filter(t=>t.done).length}</b> completados</span></div><section class="panel"><div class="tabs">${[['all','Todos'],['pending','Pendientes'],['mine','Para mí'],['done','Completados']].map(([id,title])=>`<button class="${filter===id?'active':''}" data-filter="${id}">${title}</button>`).join('')}</div>${list.length?list.map(t=>taskRow(t)).join(''):empty('Todo en su sitio','Añadid un recordatorio o disfrutad de un ratito libre.')}<p class="panel-footnote">Los recordatorios que se repiten pasan a su próxima fecha al completarlos. Los recordatorios se muestran dentro de MYC.</p></section>`;}
function shoppingPage(){const list=rows('shopping').filter(s=>filter==='pending'?!s.checked:true),all=rows('shopping'),checked=all.filter(s=>s.checked).length;return heading('Que no falte nada.','Una sola lista para cuando cualquiera de los dos pase por la tienda.','new-shopping','Añadir producto','compra')+`<section class="panel shopping-panel"><div class="shopping-progress"><span><strong>${all.length-checked}</strong> cosas por comprar</span><span>${checked} de ${all.length} en el carrito</span></div><progress max="${all.length||1}" value="${checked}" aria-label="Productos comprados"></progress><div class="tabs"><button data-filter="all" class="${filter==='all'?'active':''}">Toda la lista</button><button data-filter="pending" class="${filter==='pending'?'active':''}">Por comprar</button></div>${list.length?['Alimentación','Limpieza','Otros'].map(c=>{const group=list.filter(s=>s.category===c).sort((a,b)=>Number(a.checked)-Number(b.checked));return group.length?`<h3 class="group-label">${catIcon(c,'small')} ${c}</h3>${group.map(s=>`<div class="list-row ${s.checked?'is-done':''}"><button class="check-btn ${s.checked?'checked':''}" data-toggle="shopping" data-id="${s.id}" aria-label="${s.checked?'Desmarcar':'Comprar'} ${esc(s.title)}">${s.checked?icon('check'):''}</button><div class="row-main"><strong>${esc(s.title)}</strong><small>Añadido por ${esc(s.createdBy)}</small></div><span class="quantity">${esc(s.quantity)}</span><button class="icon-btn" data-edit="shopping" data-id="${s.id}" aria-label="Editar ${esc(s.title)}">${icon('edit')}</button></div>`).join('')}`:'';}).join(''):empty('La lista está vacía','¿Qué necesitamos para la próxima compra?','compra')}<p class="panel-footnote">Marca cada producto al meterlo en el carrito. Ambos veréis la lista actualizada.</p></section>`;}
function messagePage(){const list=rows('messages').filter(m=>filter==='all'?true:filter==='pending'?!m.resolved:m.to===api.user||m.to==='Ambos').sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return heading('Un mensaje para ti.','Peticiones, ideas y esas cosas que no queremos olvidar contarnos.','new-messages','Dejar un mensaje','mensajes')+`<div class="tabs standalone-tabs">${[['all','Todos'],['mine','Para mí'],['pending','Pendientes']].map(([id,title])=>`<button data-filter="${id}" class="${filter===id?'active':''}">${title}</button>`).join('')}</div><div class="message-grid">${list.length?list.map(m=>`<article class="message-card ${m.createdBy==='María'?'from-maria':''} ${m.resolved?'resolved':''}"><div class="message-meta">${avatar(m.createdBy)}<span><strong>${esc(m.createdBy)}</strong><small>Para ${esc(m.to)} · ${new Date(m.createdAt).toLocaleDateString('es-ES',{day:'numeric',month:'short'})}</small></span><button class="icon-btn" data-edit="messages" data-id="${m.id}" aria-label="Editar mensaje">${icon('edit')}</button></div><h2>${esc(m.title)}</h2><p class="message-body">${esc(m.body)}</p><button class="message-resolve" data-toggle="messages" data-id="${m.id}">${icon(m.resolved?'check':'heart')}${m.resolved?'Resuelto · Volver a abrir':'Marcar como resuelto'}</button></article>`).join(''):empty('Un pequeño tablón para los dos','Deja una petición, una idea o un mensaje bonito.','mensajes')}</div>`;}
function pushSupported(){return 'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window;}
function isStandalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
function isIOS(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);}
async function refreshPush(){let next='off';if(!pushSupported())next=isIOS()&&!isStandalone()?'install':'unsupported';else if(Notification.permission==='denied')next='denied';else{try{const reg=await navigator.serviceWorker.getRegistration();const sub=await reg?.pushManager.getSubscription();next=sub?'on':'off';}catch{next='off';}}if(next!==pushStatus){pushStatus=next;if(section==='settings'&&!modal.open)render();}}
function pushPanel(){if(pushStatus==='unknown')refreshPush();const texts={on:['Avisos activados en este móvil','Te llegará una notificación a la hora de cada recordatorio tuyo o de los dos.'],off:['Avisos desactivados en este móvil','Actívalos para que MYC te avise a la hora de cada recordatorio.'],install:['Primero, instala MYC','En iPhone los avisos solo funcionan con MYC en la pantalla de inicio: Safari → Compartir → «Añadir a pantalla de inicio». Luego ábrela desde ahí.'],denied:['Avisos bloqueados','Has bloqueado las notificaciones de MYC. Actívalas en los ajustes del navegador o del móvil y vuelve aquí.'],unsupported:['Este navegador no admite avisos','Prueba desde Chrome en Android o desde MYC instalada en iPhone.'],unknown:['Comprobando avisos…','']}[pushStatus];
 return `<section class="panel push-panel"><h2>${icon('bell')} Avisos de recordatorios</h2><p class="push-state ${pushStatus}"><strong>${texts[0]}</strong><small>${texts[1]}</small></p><div class="settings-actions">${pushStatus==='off'?`<button class="btn" data-action="push-on">${icon('bell')} Activar avisos</button>`:''}${pushStatus==='on'?`<button class="btn secondary" data-action="push-test">Enviar una prueba</button><button class="text-btn" data-action="push-off">Desactivar en este móvil</button>`:''}</div>${api.demo?'<small class="muted">En el modo de prueba no se envían avisos.</small>':''}</section>`;}
function urlKey(b64){const s=b64.replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(s+'==='.slice((s.length+3)%4)),c=>c.charCodeAt(0));}
async function pushOn(){
 if(busy)return;busy=true;
 try{
  if(!pushSupported())throw new Error('Este navegador no admite avisos.');
  const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Sin permiso para notificaciones no podemos avisarte.');
  const reg=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;
  const {publicKey}=await api.push('push-key');
  let sub=await reg.pushManager.getSubscription();if(sub)await sub.unsubscribe().catch(()=>{});
  sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlKey(publicKey)});
  await api.push('push-subscribe',{subscription:sub.toJSON()});
  pushStatus='on';toast('Avisos activados. Te mandamos una prueba ♡');api.push('push-test').catch(()=>{});
 }catch(e){if(e.code==='UNAUTHORIZED')reauth(e.message);else toast(e.message);}finally{busy=false;await refreshPush();render();}
}
async function pushOff(){if(busy)return;busy=true;try{const reg=await navigator.serviceWorker.getRegistration();const sub=await reg?.pushManager.getSubscription();if(sub){await api.push('push-unsubscribe',{endpoint:sub.endpoint}).catch(()=>{});await sub.unsubscribe();}toast('Avisos desactivados en este móvil.');}catch(e){toast(e.message);}finally{busy=false;pushStatus='unknown';await refreshPush();render();}}
function settingsPage(){const budget=rows('budgets').find(b=>b.month===monthNow());return heading('A nuestra manera.','Un espacio pequeño, pensado solo para nosotros.',null,null)+`<div class="two-columns"><section class="panel settings-card"><h2>María + Carlos</h2><div class="profile-pair"><div>${avatar('Carlos','large')}<strong>Carlos</strong></div><span>♡</span><div>${avatar('María','large')}<strong>María</strong></div></div><p>Casa compartida. Cuentas claras. Un equipo para todo.</p>${api.demo?`<button class="btn secondary" data-action="switch-demo">Probar como ${api.user==='Carlos'?'María':'Carlos'}</button>`:'<p class="small muted">Tu identidad la verifica Google. El acceso lo controla el servidor.</p>'}</section><section class="panel"><h2>Presupuesto de casa</h2><p class="muted">Para ${new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(new Date())}. Solo incluye los gastos compartidos.</p><div class="budget-setting"><strong>${budget?.amount?money(budget.amount):'Sin presupuesto'}</strong><button class="btn secondary" data-action="budget">Editar</button></div><p class="panel-footnote">Podéis repartir cada gasto de casa a vuestro gusto. Las compras personales siempre corresponden al 100 % a su destinatario.</p></section>${pushPanel()}<section class="panel"><h2>MYC en vuestro móvil</h2><p class="muted">Vuestro hogar, a un toque.</p><button class="btn secondary" data-action="install">${icon('download')} Instalar MYC</button><p class="small muted">En iPhone: abre MYC en Safari, pulsa Compartir y «Añadir a pantalla de inicio». En Android: usa «Instalar aplicación» en Chrome.</p><p class="small muted">La aplicación necesita internet para consultar y guardar datos compartidos. Sin conexión puede abrirse la pantalla de acceso.</p></section><section class="panel"><h2>Datos y privacidad</h2><p class="muted">Los tickets reales se guardan en Drive y se consultan con vuestra sesión. Los datos no se guardan en el móvil: solo la sesión, para no pediros Google cada vez.</p><div class="settings-actions"><button class="btn secondary" data-action="export-json">${icon('download')} Exportar datos</button>${api.demo?'<button class="text-btn danger" data-action="reset-demo">Restablecer prueba</button>':''}<button class="text-btn" data-action="logout">Cerrar sesión</button></div><small class="muted">La exportación incluye vuestros registros, sin las fotografías. Las fotografías permanecen en Drive.</small></section></div>`;}
function options(values,selected,labels={}){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(labels[v]||v)}</option>`).join('');}
function field(label,name,value='',type='text',attrs=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,name,values,value,labels={}){return `<label class="field"><span>${label}</span><select name="${name}">${options(values,value,labels)}</select></label>`;}
function openModal(table,id){
 if(busy)return;editedId=id||null;pendingPayload=null;
 const r=rows(table).find(e=>e.id===id)||{};
 const titles={expenses:'Un gasto más, una cuenta menos.',tasks:'Un nuevo recordatorio.',shopping:'Para la próxima compra.',messages:'Algo que contarte.',settlements:'Un pago entre nosotros.',budgets:'Nuestro presupuesto.'};
 let body='';
 if(table==='expenses')body=field('¿Qué habéis comprado?','title',r.title||'','text','required maxlength="160" placeholder="Ej. Compra de la semana"')+`<div class="form-grid">${field('Importe (€)','amount',r.amount?String(r.amount/100).replace('.',','):'','text','required inputmode="decimal" placeholder="0,00"')}${field('Fecha','date',r.date||today(),'date','required min="2000-01-01" max="2100-12-31"')}${select('¿Quién ha pagado?','paidBy',PEOPLE,r.paidBy||api.user)}${select('Tienda','store',STORES,r.store||'Supermercado',Object.fromEntries(STORES.map(s=>[s,storeEmoji(s)+' '+s])))}</div>`+select('¿De quién es el gasto?','purpose',['household',...PEOPLE],r.purpose||'household',{household:'🏠 De casa · compartido',Carlos:'👨 Para Carlos · él asume el 100 %',María:'👩 Para María · ella asume el 100 %'})+`<div id="split-field" ${r.purpose&&r.purpose!=='household'?'hidden':''}>${field('Porcentaje que corresponde a Carlos (%)','carlosPercent',r.carlosPercent??50,'number','min="0" max="100" step="1" required')}<small class="muted">El resto corresponde a María. Con 50, se reparte a medias.</small></div>`+catPicker('category',CATEGORIES,r.category||'Alimentación')+`<div class="split-preview" id="split-preview"></div>`+notes(r.notes)+`${r.receiptId||r.demoReceipt?'<p class="receipt-existing">✓ Este gasto ya tiene un ticket adjunto.</p>':'<label class="upload-field"><span>📷 Foto del ticket <small>Opcional · JPEG, PNG o WebP · hasta 15 MB</small></span><input name="receipt" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="small muted">Puedes elegir una foto de tu cámara. Se reducirá de tamaño y se convertirá a JPEG antes de enviarla.</p>'}`;
 if(table==='tasks')body=field('¿Qué hay que hacer?','title',r.title||'','text','required maxlength="160"')+`<div class="form-grid">${select('¿Quién se encarga?','assignedTo',[...PEOPLE,'Ambos'],r.assignedTo||api.user)}${field('¿Para cuándo?','due',r.due||'','date','min="2000-01-01" max="2100-12-31"')}</div><div class="form-grid">${field('¿A qué hora? <small>opcional</small>','time',r.time||'','time','step="300"')}</div>${remindPicker(r.id?remindList(r):['60','0'])}`+select('Repetir','recurrence',['none','daily','weekly','monthly'],r.recurrence||'none',{none:'No se repite',daily:'Cada día',weekly:'Cada semana',monthly:'Cada mes'})+notes(r.notes)+`<input type="hidden" name="done" value="${r.done?'true':'false'}">`;
 if(table==='shopping')body=field('Producto','title',r.title||'','text','required maxlength="100" placeholder="Ej. Leche"')+field('Cantidad','quantity',r.quantity||'1','text','required maxlength="40" placeholder="Ej. 2 briks"')+catPicker('category',['Alimentación','Limpieza','Otros'],r.category||'Alimentación')+`<input type="hidden" name="checked" value="${r.checked?'true':'false'}">`;
 if(table==='messages')body=field('Título','title',r.title||'','text','required maxlength="120" placeholder="¿Qué te gustaría contar?"')+select('Para','to',[...PEOPLE,'Ambos'],r.to||(api.user==='Carlos'?'María':'Carlos'))+`<label class="field"><span>Mensaje</span><textarea name="body" required maxlength="2000" rows="5">${esc(r.body||'')}</textarea></label><input type="hidden" name="resolved" value="${r.resolved?'true':'false'}">`;
 if(table==='settlements'){const b=balance(rows('expenses'),rows('settlements'));body=`<p class="muted">Apunta un pago que ya os hayáis hecho por Bizum, transferencia o en efectivo. MYC registra el pago; no mueve dinero.</p>`+select('¿Quién paga a quién?','from',PEOPLE,r.from||settlePreset?.from||(b>=0?'María':'Carlos'),{Carlos:'Carlos paga a María',María:'María paga a Carlos'})+field('Importe pagado (€)','amount',r.amount?String(r.amount/100).replace('.',','):settlePreset?(settlePreset.amount/100).toFixed(2).replace('.',','):Math.abs(b)?String(Math.abs(b)/100).replace('.',','):'','text','required inputmode="decimal"')+field('Fecha','date',r.date||today(),'date','required min="2000-01-01" max="2100-12-31"')+notes(r.notes||(settlePreset?.note||''));settlePreset=null;}
 if(table==='budgets')body=`<p>Presupuesto para ${esc(monthNow())}. Escribe 0 para dejarlo sin límite.</p>`+`<input type="hidden" name="month" value="${monthNow()}">`+field('Presupuesto de casa (€)','amount',r.amount?r.amount/100:'','text','required inputmode="decimal"');
 modal.innerHTML=`<form id="record-form" data-table="${table}" data-id="${r.id||crypto.randomUUID()}" data-version="${r.version||0}"><div class="dialog-head"><div><span class="eyebrow">${r.id?'EDITAR':'PARA NUESTRO HOGAR'}</span><h2 id="dialog-title">${titles[table]}</h2></div><button type="button" class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body">${body}<p id="form-error" class="error-text" role="alert"></p></div><div class="dialog-footer">${r.id&&table!=='budgets'?'<button type="button" class="text-btn danger" data-action="delete-record">Eliminar</button>':'<span></span>'}<div><button type="button" class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn" type="submit">Guardar</button></div></div></form>`;
 modal.showModal();if(table==='expenses')updateSplit();
}
function notes(value=''){return `<label class="field"><span>Una nota <small>opcional</small></span><textarea name="notes" maxlength="1000" rows="2">${esc(value)}</textarea></label>`;}
function updateSplit(){const form=$('#record-form');if(!form||form.dataset.table!=='expenses')return;const p=form.elements.purpose.value;$('#split-field').hidden=p!=='household';let amount=0;try{amount=cents(form.elements.amount.value);}catch{}const percent=p==='Carlos'?100:p==='María'?0:Number(form.elements.carlosPercent.value);const c=Math.round(amount*percent/100);$('#split-preview').innerHTML=`<strong>Así se reparte</strong><span>Carlos: ${money(c)} · María: ${money(amount-c)}</span>`;}
async function compressReceipt(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw new Error('Elige una imagen JPEG, PNG o WebP de menos de 15 MB.');
 const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.naturalWidth||img.naturalWidth*img.naturalHeight>80000000)throw new Error('La imagen tiene demasiada resolución. Elige una foto más pequeña.');const scale=Math.min(1,1800/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let data;for(const quality of [.82,.65,.45]){data=canvas.toDataURL('image/jpeg',quality).split(',')[1];if(data.length<1260000)return {mime:'image/jpeg',base64:data};}throw new Error('El ticket sigue siendo demasiado grande. Prueba una foto más pequeña.');}finally{URL.revokeObjectURL(url);}}
async function saveForm(form){
 if(busy)return;$('#form-error').textContent='';
 const table=form.dataset.table,fd=new FormData(form),record=Object.fromEntries([...fd].filter(([k])=>k!=='receipt'));record.done=fd.get('done')==='true';if(table==='tasks'){record.remind=fd.getAll('remind');if(!record.due)record.time='';}record.checked=fd.get('checked')==='true';record.resolved=fd.get('resolved')==='true';
 try{if('amount'in record)record.amount=table==='budgets'&&/^0([,.]0{1,2})?$/.test(record.amount.trim())?0:cents(record.amount);if(table==='expenses')record.carlosPercent=Number(record.carlosPercent);
 busy=true;form.querySelector('[type="submit"]').disabled=true;form.querySelector('[type="submit"]').textContent='Guardando…';
 const fingerprint=JSON.stringify(record)+'|'+(fd.get('receipt')?.name||'')+'|'+(fd.get('receipt')?.size||0);
 if(!pendingPayload||pendingPayload.fingerprint!==fingerprint){const receipt=fd.get('receipt')?.size?await compressReceipt(fd.get('receipt')):undefined;pendingPayload={fingerprint,payload:{kind:'save',table,id:form.dataset.id,expectedVersion:Number(form.dataset.version),operationId:crypto.randomUUID(),record,...(receipt?{receipt}:{})}};}
 const result=await api.mutate(pendingPayload.payload);applyRecord(table,result.record);modal.close();pendingPayload=null;toast('Guardado. Una cosa menos en la cabeza ♡');
 }catch(e){if(e.code==='UNAUTHORIZED'){reauth(e.message);return;}$('#form-error').textContent=e.message;if(e.code==='CONFLICT'){await sync(true,true);$('#form-error').textContent=e.message+' Cierra este formulario y vuelve a abrir el registro actualizado.';}}finally{busy=false;if(active)render();if(form.isConnected){const button=form.querySelector('[type="submit"]');button.disabled=false;button.textContent='Guardar';}}
}
function applyRecord(table,record){const index=state[table].findIndex(r=>r.id===record.id);if(index<0)state[table].push(record);else state[table][index]=record;syncTime=new Date();syncError='';requestSeq++;}
async function sync(quiet=false,force=false){
 if($('#reauth'))return;
 if(!active||(!force&&(busy||modal.open||document.activeElement?.matches('input,textarea,select'))))return;
 const seq=++requestSeq;try{const data=await api.snapshot();if(seq!==requestSeq||!active)return;state=data;syncTime=new Date();syncError='';if(!modal.open)render();if(!quiet)toast(api.demo?'Datos de prueba actualizados.':'Datos actualizados desde Google.');}catch(e){if(seq!==requestSeq||!active)return;if(e.code==='UNAUTHORIZED'){if(!api.demo)reauth(e.message);return;}syncError=e.message;if(!modal.open)render();}
}
const operationRetries=new Map();
async function toggle(table,id){if(busy)return;const r=rows(table).find(r=>r.id===id);if(!r)return;const record={...r};let kind='save';if(table==='tasks'){if(r.done)record.done=false;else kind='completeTask';}if(table==='shopping')record.checked=!r.checked;if(table==='messages')record.resolved=!r.resolved;
 const key=table+id,previous=operationRetries.get(key);const p=previous||{table,id,expectedVersion:r.version,operationId:crypto.randomUUID(),kind,record};busy=true;
 try{const result=await api.mutate(p);applyRecord(table,result.record);operationRetries.delete(key);toast(table==='tasks'&&r.recurrence!=='none'&&!r.done?'Hecha. Ya está preparada la próxima fecha.':'Actualizado ♡');}catch(e){if(e.code==='NETWORK'||e.code==='TIMEOUT')operationRetries.set(key,p);else operationRetries.delete(key);if(e.code==='UNAUTHORIZED'){reauth(e.message);return;}toast(e.message);if(e.code==='CONFLICT')await sync(true,true);}finally{busy=false;if(active)render();}}
function confirmDialog(title,description,onConfirm){modal.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body"><p>${description}</p><p id="confirm-error" class="error-text" role="alert"></p></div><div class="dialog-footer"><button class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn danger-btn" id="confirm-yes">Confirmar</button></div>`;if(!modal.open)modal.showModal();$('#confirm-yes').onclick=onConfirm;}
function deleteRecord(){const form=$('#record-form');const table=form.dataset.table,id=form.dataset.id,version=Number(form.dataset.version);const p={table,id,expectedVersion:version,operationId:crypto.randomUUID(),kind:'delete'};confirmDialog('¿Eliminar este registro?','Desaparecerá de la aplicación en los dos móviles. El ticket, si lo tiene, se conservará privado en Drive.',async()=>{if(busy)return;busy=true;$('#confirm-yes').disabled=true;try{const result=await api.mutate(p);applyRecord(table,result.record);modal.close();toast('Registro eliminado.');}catch(e){$('#confirm-error').textContent=e.message;if(e.code==='UNAUTHORIZED')reauth(e.message);if(e.code==='CONFLICT')await sync(true,true);}finally{busy=false;if(active)render();if($('#confirm-yes'))$('#confirm-yes').disabled=false;}});}
function download(name,body,type){const blob=new Blob([body],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csv(){const header=['Fecha','Concepto','Tienda','Tipo','Pagó','Importe EUR','Porcentaje Carlos','Categoría'];const cell=v=>'"'+String(v).replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const data=rows('expenses').filter(e=>e.date.startsWith(month)).map(e=>[e.date,e.title,e.store,e.purpose==='household'?'Casa':'Para '+e.purpose,e.paidBy,(e.amount/100).toFixed(2).replace('.',','),e.carlosPercent,e.category]);download('MYC-gastos-'+month+'.csv','\uFEFF'+[header,...data].map(row=>row.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
async function showReceipt(id){try{const blob=await api.receipt(id);if(receiptUrl)URL.revokeObjectURL(receiptUrl);receiptUrl=URL.createObjectURL(blob);modal.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">Nuestro ticket</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body ticket-view"><img src="${receiptUrl}" alt="Foto del ticket"><a class="btn secondary" href="${receiptUrl}" download="MYC-ticket.jpg">${icon('download')} Guardar foto</a></div>`;modal.showModal();}catch(e){toast(e.message);}}
async function action(name){
 if(name==='demo'){api.demoLogin();state=await api.snapshot();startApp();}
 if(name==='logout'){if(busy)return;if(api.demo){modal.close();loginScreen();return;}confirmDialog('¿Cerrar sesión en este móvil?','Tendrás que volver a entrar con Google y dejarán de llegarte avisos aquí. Tus datos no se borran.',async()=>{try{const reg=await navigator.serviceWorker?.getRegistration();const sub=await reg?.pushManager?.getSubscription();if(sub){await api.push('push-unsubscribe',{endpoint:sub.endpoint}).catch(()=>{});await sub.unsubscribe().catch(()=>{});}}catch{}modal.close();window.google?.accounts.id.disableAutoSelect();pushStatus='unknown';loginScreen();});}
 if(name==='retry-boot')await boot();
 if(name==='push-on')await pushOn();
 if(name==='push-off')await pushOff();
 if(name==='push-test'){try{await api.push('push-test');toast('Prueba enviada. Debería llegarte en unos segundos.');}catch(e){if(e.code==='UNAUTHORIZED')reauth(e.message);else toast(e.message);}}
 if(name==='sync')await sync();
 if(name.startsWith('new-'))openModal(name.slice(4));
 if(name==='settle')openModal('settlements');
 if(name==='budget')openModal('budgets',rows('budgets').find(b=>b.month===monthNow())?.id);
 if(name==='close-modal'&&!busy)modal.close();
 if(name==='delete-record')deleteRecord();
 if(name==='switch-demo'&&api.demo){api.user=api.user==='Carlos'?'María':'Carlos';render();}
 if(name==='prev-month'||name==='next-month'){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+(name==='next-month'?1:-1));month=d.toISOString().slice(0,7);render();}
 if(name==='export-csv')csv();
 if(name==='export-json')download('MYC-datos-'+today()+'.json',JSON.stringify(Object.fromEntries(TABLES.map(t=>[t,rows(t)])),null,2),'application/json');
 if(name==='reset-demo'&&api.demo)confirmDialog('¿Restablecer la prueba?','Se borrarán los cambios de ejemplo de este navegador. Los datos reales no se ven afectados.',()=>{api.resetDemo();state=api.demoState();modal.close();render();});
 if(name==='install'){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else confirmDialog('MYC en la pantalla de inicio','En iPhone: Safari → Compartir → Añadir a pantalla de inicio. En Android: menú de Chrome → Instalar aplicación. Requiere abrir MYC desde su dirección HTTPS publicada.',()=>modal.close());}
}
document.addEventListener('click',async e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.nav){e.preventDefault();if(busy)return;section=target.dataset.nav;filter='all';search='';render();window.scrollTo({top:0,behavior:'smooth'});}else if(target.dataset.action==='settle-month'){e.preventDefault();settlePreset={from:target.dataset.from,amount:Number(target.dataset.amount),note:'Cuentas de '+new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric'}).format(new Date(month+'-15T12:00:00Z'))};openModal('settlements');}else if(target.dataset.action){e.preventDefault();await action(target.dataset.action);}else if(target.dataset.edit)openModal(target.dataset.edit,target.dataset.id);else if(target.dataset.toggle)await toggle(target.dataset.toggle,target.dataset.id);else if(target.dataset.filter){filter=target.dataset.filter;render();}else if(target.dataset.receipt)await showReceipt(target.dataset.receipt);});
document.addEventListener('submit',e=>{if(e.target.id==='record-form'){e.preventDefault();saveForm(e.target);}});
document.addEventListener('input',e=>{if(e.target.closest('#record-form'))updateSplit();if(e.target.id==='search'){const start=e.target.selectionStart;search=e.target.value;render();const input=$('#search');input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('change',e=>{if(e.target.id==='month'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;render();}if(e.target.name==='purpose')updateSplit();});
modal.addEventListener('cancel',e=>{if(busy)e.preventDefault();});modal.addEventListener('close',()=>{if(receiptUrl){URL.revokeObjectURL(receiptUrl);receiptUrl=null;}});
window.addEventListener('online',()=>{if(active)sync(true);});window.addEventListener('offline',()=>{if(active){syncError='Sin conexión. Los cambios necesitan internet.';render();}});
window.addEventListener('focus',()=>sync(true));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')sync(true);});window.addEventListener('storage',e=>{if(e.key==='myc-demo-v2'&&api.demo)sync(true);});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
navigator.serviceWorker?.addEventListener('message',e=>{const target=e.data?.type==='open'&&e.data.section;if(target&&sections[target]&&active&&!modal.open){section=target;filter='all';render();}});
boot();
